script:
(function () {
  'use strict';
  // Auto loan early payoff: extra monthly and one-time payments on an existing simple-interest loan.
  //   Each month: interest = balance x APR / 12; the scheduled payment (plus any extra) goes to that
  //   interest first and the rest to principal; the last payment is only what is left owing.
  //   The plan with extras is compared with the same loan paid exactly as scheduled.
  // Verified in Node (scratchpad tests/b3auto): $20,000 at 6% with the standard 60-month payment of
  //   $386.66 pays off in 60 months with $3,199.36 of interest (closed form PMT x n - P); adding
  //   $100/month pays off in 47 months (closed-form NPER 46.12) with $2,444.38 of interest (within $0.13
  //   of PMT x NPER - P), saving $754.98; a $20,000 balance at 0% paid $500/month takes exactly 40 months; a payment that does not cover the first month's interest is
  //   rejected; no NaN or Infinity reaches the page on bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September',
                'October', 'November', 'December'];
  var MAX_MONTHS = 600;
  var last = null;

  function el(id) { return document.getElementById(id); }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  // Pays the loan down month by month. Returns null if the balance would never be repaid.
  function payoff(balance, annualRate, payment, extra, lump, lumpMonth) {
    var i = annualRate / 12, bal = balance, rows = [], totalInterest = 0;
    for (var m = 1; bal > 0.005; m++) {
      if (m > MAX_MONTHS) return null;
      var interest = bal * i;
      var pay = payment + extra + (m === lumpMonth ? lump : 0);
      if (pay > bal + interest) pay = bal + interest;
      var principal = pay - interest;
      if (principal <= 0) return null;
      bal -= principal;
      if (bal < 0.005) bal = 0;
      totalInterest += interest;
      rows.push({ n: m, payment: pay, interest: interest, principal: principal, balance: bal });
    }
    return { rows: rows, months: rows.length, totalInterest: totalInterest };
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  // "YYYY-MM" of the next payment -> label of the month of payment number n (1-based).
  function payoffLabel(start, n) {
    var match = /^(\d{4})-(\d{2})$/.exec(start || '');
    if (!match) return 'after ' + n + (n === 1 ? ' payment' : ' payments');
    var idx = Number(match[1]) * 12 + Number(match[2]) - 1 + n - 1;
    return MONTHS[idx % 12] + ' ' + Math.floor(idx / 12);
  }

  function setText(id, text) { el(id).textContent = text; }

  function clearResults() {
    ['epInterestSaved', 'epTimeSaved', 'epNewPayoff', 'epOldPayoff', 'epOldInterest', 'epNewInterest',
     'epOldMonths', 'epNewMonths', 'epNewPayment'].forEach(function (id) { setText(id, '–'); });
    el('epSchedule').innerHTML = '';
    last = null;
  }

  function renderSchedule() {
    var head = el('epScheduleHead'), body = el('epSchedule');
    if (!last) { body.innerHTML = ''; return; }
    var html = [], base = last.base.rows, plan = last.plan.rows;
    function baseBal(n) { return n <= base.length ? base[n - 1].balance : 0; }
    if (el('epView').value === 'month') {
      head.innerHTML = '<tr><th scope="col">Month</th><th scope="col">Payment</th><th scope="col">Interest</th><th scope="col">Balance with extra payments</th><th scope="col">Balance as scheduled</th></tr>';
      for (var n = 1; n <= base.length; n++) {
        var r = plan[n - 1];
        html.push('<tr><td>' + n + '</td><td>' + money.format(r ? r.payment : 0) + '</td><td>' +
          money.format(r ? r.interest : 0) + '</td><td>' + money.format(r ? r.balance : 0) + '</td><td>' +
          money.format(baseBal(n)) + '</td></tr>');
      }
    } else {
      head.innerHTML = '<tr><th scope="col">Year</th><th scope="col">Paid</th><th scope="col">Interest</th><th scope="col">Balance with extra payments</th><th scope="col">Balance as scheduled</th></tr>';
      var paid = 0, intr = 0;
      for (var k = 1; k <= base.length; k++) {
        var p = plan[k - 1];
        if (p) { paid += p.payment; intr += p.interest; }
        if (k % 12 === 0 || k === base.length) {
          html.push('<tr><td>' + Math.ceil(k / 12) + '</td><td>' + money.format(paid) + '</td><td>' +
            money.format(intr) + '</td><td>' + money.format(p ? p.balance : 0) + '</td><td>' +
            money.format(baseBal(k)) + '</td></tr>');
          paid = 0; intr = 0;
        }
      }
    }
    body.innerHTML = html.join('');
  }

  function update() {
    var balance = read('epBalance'), rate = read('epRate'), payment = read('epPayment'),
        extra = read('epExtra', true), lump = read('epLump', true), lumpMonth = read('epLumpMonth', true),
        start = String(el('epStart').value || '').trim();
    var error = el('epError'), msg = '';
    if (isNaN(balance) || balance <= 0) msg = 'Enter a loan balance greater than $0.';
    else if (isNaN(rate) || rate < 0 || rate > 40) msg = 'Enter an interest rate from 0% to 40%.';
    else if (isNaN(payment) || payment <= 0) msg = 'Enter your current monthly payment.';
    else if ([extra, lump].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Extra payments cannot be negative.';
    else if (lump > 0 && (isNaN(lumpMonth) || lumpMonth < 1 || lumpMonth > MAX_MONTHS || lumpMonth % 1 !== 0)) msg = 'Enter the payment number for the one-time payment (1 for your next payment).';
    else if (payment <= balance * rate / 1200) msg = 'That payment does not cover the monthly interest, so the loan would never be repaid. Check the balance, rate and payment.';
    var base = msg ? null : payoff(balance, rate / 100, payment, 0, 0, 0);
    if (!msg && !base) msg = 'At that payment the loan would take more than 50 years to repay. Check the balance, rate and payment.';
    if (msg) { error.hidden = false; error.textContent = msg; clearResults(); return; }
    var plan = payoff(balance, rate / 100, payment, extra, lump, lumpMonth);
    error.hidden = true;
    error.textContent = '';

    var saved = Math.max(0, base.totalInterest - plan.totalInterest);
    setText('epInterestSaved', money.format(saved));
    setText('epTimeSaved', duration(Math.max(0, base.months - plan.months)));
    setText('epNewPayoff', payoffLabel(start, plan.months));
    setText('epOldPayoff', payoffLabel(start, base.months));
    setText('epOldInterest', money.format(base.totalInterest));
    setText('epNewInterest', money.format(plan.totalInterest));
    setText('epOldMonths', duration(base.months));
    setText('epNewMonths', duration(plan.months));
    setText('epNewPayment', money.format(payment + extra));
    last = { base: base, plan: plan };
    renderSchedule();
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('epForm');
    if (!form) return;
    var start = el('epStart');
    if (!start.value) {
      var d = new Date(), idx = d.getFullYear() * 12 + d.getMonth() + 1;
      start.value = Math.floor(idx / 12) + '-' + ('0' + (idx % 12 + 1)).slice(-2);
    }
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('epView').addEventListener('change', renderSchedule);
    update();
  });
})();
